import { createSelector, createFeatureSelector } from '@ngrx/store';
import { TempleState } from './temple.reducer';

export const selectTempleState = createFeatureSelector<TempleState>('temple');

export const selectAllTemples = createSelector(
    selectTempleState,
    (state: TempleState) => state.temples
);

export const selectTempleLoading = createSelector(
    selectTempleState,
    (state: TempleState) => state.loading
);
